import {AIClient} from './ai-client.js?v=20261027-public1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function openOwnerPanel({modal,client}){const d=modal('<p>正在连接本机加密管理凭据…</p>','网站 AI · 所有者管理');(async()=>{try{const access=await client.request('/api/classroom-teacher/access'),remote=new AIClient(access.backend,access.token),info=await remote.request('/api/admin'),box=document.createElement('div');box.innerHTML=`<div class="notice">已验证所有者权限。模型密钥与管理令牌不会在网页中回显。今日模型调用 ${info.today.calls} 次，保守记账 ${info.today.tokens} tokens。</div><form><label class="level-chip"><input name="enabled" type="checkbox" ${info.enabled?'checked':''}>允许网站访客使用 AI</label><div class="form-grid">${[['requestsPerMinute','同一网络每分钟操作',info.limits.requestsPerMinute],['commentsPerNetworkDay','同一网络每日评论',info.limits.commentsPerNetworkDay],['plansPerNetworkDay','同一网络每日方案',info.limits.plansPerNetworkDay],['concurrency','全站同时模型请求',info.limits.concurrency],['commentsPerSession','每个访客会话评论',info.limits.comments],['plansPerSession','每个访客会话方案',info.limits.plans],['summariesPerSession','每个访客会话摘要批次',info.limits.summaries],['requestsPerSession','每个访客会话操作',info.limits.requests],['dailyCalls','全站每日模型调用',info.dailyCalls],['dailyTokens','全站每日 token 保守上限',info.dailyTokens]].map(([k,l,v])=>`<label>${l}<input type="number" name="${k}" min="0" max="10000000" value="${v}" required></label>`).join('')}</div><button class="primary">保存网站服务设置</button><p id="owner-result" role="status"></p></form><p class="muted">额度按北京时间日界线累计；失败请求可能按预留用量计入，不等于供应商账单。关闭服务会阻止新的模型操作，不撤回已发出的请求。</p>`;d.append(box);d.querySelector(':scope > p')?.remove();box.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data=Object.fromEntries(f);data.enabled=!!f.get('enabled');try{await remote.request('/api/admin',data);box.querySelector('#owner-result').textContent='设置已保存，后续请求立即按新限制处理。';}catch(e){box.querySelector('#owner-result').textContent=e.message;}};}catch(e){const p=document.createElement('p');p.className='notice error';p.textContent=e.message;d.append(p);}})();return d;}
